var RULES='《花学社社区总版规》v2.0\n一、总则：花学社是面向大众学习者的学习交流社区，提倡真诚分享、友善互助、专注学习。注册即视为同意本版规。\n二、账号：一人一号严禁小号；Lv.1新用户24h内仅可浏览。\n三、发帖：内容与板块相符、标题简明、主题帖最低2汉字；禁止水帖/刷屏/恶意填分类。\n四、红线：1.链接/二维码：首次拦截不扣分；24h内累计3次→扣30分+禁言7天；5次以上→永久封号+封设备。2.黄赌毒→清分封号封设备。3.辱骂→首次扣10+禁1天再犯扣20+禁3天。4.造谣→同辱骂。5.政治→扣50封号。6.广告引流→扣10~50+禁言/封号。7.侵犯隐私→扣20+禁3天。8.脚本刷分→清分封号封设备。9.挂机→弹验证码/扣20分。10.刷屏→扣20+禁3天。11.无意义评论24h超10条→扣20+禁3天。12.频繁删帖≥5次→禁1天。13.恶意举报→按引战处理。\n五、奖励：签到+2经验+1硬币（连续7天+1/+2，30天+3/+5）；发帖+1经验+2硬币（日限1）；评论+1经验+1硬币（日限1）；被好评+2经验+2信誉分；解题+5经验+5信誉分（日限2）；邀请+25硬币（月限5）；举报成立+3经验+3信誉分+10硬币；阅读简报+1经验+1硬币（日限1）。\n六、等级：0/30/80/160/300/500/800/1200/1800/2500经验。\n七、硬币：打赏1~10枚/次；硬币商店后期。\n八、信誉分(满分100)：80~100正常；60~80减半；40~60禁3天+人工审核；20~40禁7天+仅浏览；0~20永久禁言。\n九、好评每帖仅1次/日限1次；点赞无限制。\n十、评论删除扣回奖励+50%罚金。\n十一、最终解释权归管理员。';
var WELCOME='📜 红线：链接/二维码累计3次→扣30分+禁7天，5次→封号封设备；黄赌毒→清分封号；辱骂→首次扣10+禁1天再犯扣20+禁3天；政治→扣50封号。\n🪙 每日：签到+1硬币、发帖+2、评论+1、阅读简报+1；日限1次。\n⚡ 每日经验上限4点。\n💯 信誉分满分100，低于80权限受限。\n⛔ 挂机超2h弹验证码。\n👶 Lv.1新用户24h内仅浏览。';
function $(id){return document.getElementById(id);}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function fmt(t){if(!t)return'';var d=new Date(t),n=new Date(),p=function(x){return String(x).padStart(2,'0');};return d.toDateString()===n.toDateString()?p(d.getHours())+':'+p(d.getMinutes()):(d.getMonth()+1)+'月'+d.getDate()+'日';}
function toast(m){var t=$('toast');if(!t)return;t.textContent=m;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(function(){t.classList.remove('show');},2200);}
function did(){var d=localStorage.getItem('did');if(!d){d='dev-'+Math.random().toString(36).slice(2)+Date.now().toString(36);localStorage.setItem('did',d);}return d;}
function authH(){var h={'apikey':SUPABASE_ANON_KEY,'Content-Type':'application/json'};var t=localStorage.getItem('sb_token');if(t)h['Authorization']='Bearer '+t;return h;}
async function refreshT(){var rt=localStorage.getItem('sb_refresh');if(!rt)throw new Error('no rt');var r=await fetch(SUPABASE_URL+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{'apikey':SUPABASE_ANON_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:rt})});var j=await r.json();if(j&&j.access_token){localStorage.setItem('sb_token',j.access_token);localStorage.setItem('sb_refresh',j.refresh_token);return j.access_token;}throw new Error('refresh failed');}
async function api(path,opt){opt=opt||{};var h=authH();if(opt.headers)for(var k in opt.headers)h[k]=opt.headers[k];var res=await fetch(SUPABASE_URL+path,{...opt,headers:h});if(res.status===401){try{await refreshT();var h2=authH();if(opt.headers)for(var k2 in opt.headers)h2[k2]=opt.headers[k2];res=await fetch(SUPABASE_URL+path,{...opt,headers:h2});}catch(e){logout();throw new Error('登录已过期');}}if(!res.ok){var m='HTTP '+res.status;try{var j=await res.json();m=j.msg||j.message||j.hint||m;}catch(e){}throw new Error(m);}var txt=await res.text();if(!txt)return null;try{return JSON.parse(txt);}catch(e){return txt;}}
function qs(o){var r=[];for(var k in o)r.push(encodeURIComponent(k)+'='+encodeURIComponent(o[k]));return r.join('&');}
function dbI(t,b){return api('/rest/v1/'+t,{method:'POST',headers:{'Prefer':'return=representation'},body:JSON.stringify(b)});}
function dbU(t,f,b){return api('/rest/v1/'+t+'?'+f,{method:'PATCH',headers:{'Prefer':'return=representation'},body:JSON.stringify(b)});}
function dbD(t,f){return api('/rest/v1/'+t+'?'+f,{method:'DELETE'});}
function dbR(f,a){return api('/rest/v1/rpc/'+f,{method:'POST',body:JSON.stringify(a||{})});}
function expLv(l){var t={1:0,2:30,3:80,4:160,5:300,6:500,7:800,8:1200,9:1800,10:2500};return t[l]||2500;}
