async function submitReport(type,tid){var sel=[];document.querySelectorAll('.rr:checked').forEach(function(x){sel.push(REPORT_REASONS[+x.dataset.r]);});if(!sel.length){toast('请至少勾选一个原因');return;}try{await dbI('reports',{target_type:type,target_id:tid,reason:sel.join('、'),reporter_id:me.id});toast('🚩举报成功，成立有奖');hideReport();}catch(e){toast('举报失败');}}

