async function openUser(uid){if(!uid)return;curUser=uid;try{var r=await api('/rest/v1/profiles?select=*&id=eq.'+uid);var u=r&&r[0];if(!u){toast('用户不存在');return;}var isMe2=me&&me.id===uid;var fol=me?await api('/rest/v1/followers?follower_id=eq.'+me.id+'&following_id=eq.'+uid+'&limit=1'):null;var folN=await api('/rest/v1/followers?following_id=eq.'+uid+'&select=id');var fanN=await api('/rest/v1/followers?follower_id=eq.'+uid+'&select=id');var pct=Math.min(100,Math.round((u.exp-expLv(u.level))/(expLv(u.level+1)-expLv(u.level))*100));var editBtn=isMe2?'<div style="margin-top:8px"><span style="background:#F0E6FF;color:#7B68EE;padding:5px 20px;border-radius:14px;font-size:12px;cursor:pointer" onclick="goPage(\'editPage\')">✏️ 编辑资料</span></div>':'';var folBtn=isMe2?'':'<span class="follow-btn '+(fol&&fol.length?'':'on')+'" style="background:'+(fol&&fol.length?'#eee':'linear-gradient(135deg,#7B68EE,#6A5ACD)')+';color:'+(fol&&fol.length?'#555':'#fff')+'" onclick="'+(fol&&fol.length?'unfollowUser(\''+uid+'\')':'followUser(\''+uid+'\')')+'">'+(fol&&fol.length?'已关注':'＋关注')+'</span>';var ub=$('userBox');if(!ub)return;ub.innerHTML='<div class="ubg">'+(u.bg_image?'<img src="'+esc(u.bg_image)+'" onerror="this.parentNode.style.background=\'linear-gradient(135deg,#7B68EE,#6A5ACD)\'">':'')+'</div><div class="ubg-avatar-wrap"><div class="ubg-avatar2">'+(u.avatar_url?'<img src="'+esc(u.avatar_url)+'">':esc((u.nickname||'友')[0]))+'</div></div><div class="uinfo"><div class="uname">'+esc(u.nickname)+(u.role==='admin'?'<span class="utag">管理员</span>':'')+'</div>'+(me&&me.role==='admin'&&!isMe2?'<div style="font-size:12px;color:#999;margin-top:3px">QQ：'+esc(u.qq||'-')+'</div>':'')+'<div class="pt-exp"><i style="width:'+Math.max(4,pct)+'%"></i></div><div class="pt-exp-t">Lv'+u.level+'·经验'+u.exp+'/'+expLv(u.level+1)+'</div><div style="font-size:12px;color:#666;margin-top:6px">'+esc(u.bio||'这个人很懒')+'</div><div class="stat-card" style="margin-top:8px"><div><div class="stat-num" style="color:#ff9500">🪙'+u.coins+'</div><div class="stat-label">硬币</div></div><div><div class="stat-num" style="color:#7B68EE">'+(folN?folN.length:0)+'</div><div class="stat-label">关注</div></div><div><div class="stat-num" style="color:#6A5ACD">'+(fanN?fanN.length:0)+'</div><div class="stat-label">粉丝</div></div></div>'+editBtn+folBtn+'</div>';loadUserPosts('posts');goPage('userPage');}catch(e){toast('加载失败');}}
async function loadUserPosts(tab){try{var ut1=$('ut1'),ut2=$('ut2');if(ut1)ut1.classList.toggle('on',tab==='posts');if(ut2)ut2.classList.toggle('on',tab==='comments');var ul=$('userList');if(!ul)return;if(tab==='posts'){var d=await api('/rest/v1/posts?select=*,author_id(nickname,level)&author_id=eq.'+curUser+'&status=eq.published&order=created_at.desc&limit=50');renderCards(d,ul,'TA还没有发过帖子');}else{var d2=await api('/rest/v1/comments?select=*,author_id(nickname,level)&author_id=eq.'+curUser+'&status=eq.published&order=created_at.desc&limit=50');ul.innerHTML=(!d2||!d2.length)?'<div class="empty">TA还没有评论</div>':d2.map(function(c){return'<div class="comment-box"><div class="cb-text">'+esc(c.content)+'</div><div class="cb-time">'+fmt(c.created_at)+'</div></div>';}).join('');}}catch(e){var ul2=$('userList');if(ul2)ul2.innerHTML='<div class="empty">加载失败</div>';}}
