async function loadRank(type){rank=type;try{var tg=$('tabGood'),tl=$('tabLike'),tv=$('tabLevel');if(tg)tg.classList.toggle('on',type==='good');if(tl)tl.classList.toggle('on',type==='like');if(tv)tv.classList.toggle('on',type==='level');}catch(e){}var rl=$('rankList');if(!rl)return;rl.innerHTML='<div class="empty">加载中...</div>';try{if(type==='good'){var d=await api('/rest/v1/posts?select=*,author_id(nickname,level)&status=eq.published&order=good_count.desc&limit=20');rl.innerHTML=(!d||!d.length)?'<div class="empty">暂无</div>':d.map(function(p,i){return'<div class="rank-item"><div class="rank-no '+(i<3?'top'+(i+1):'')+'">'+(i+1)+'</div><div style="flex:1;margin-left:6px"><div style="font-size:13px">'+esc(p.title)+'</div><div style="font-size:11px;color:#999">👤'+esc(p.author_id?p.author_id.nickname||'':'')+'</div></div><div style="font-size:13px;color:#ff9500;font-weight:600">❤️'+p.good_count+'</div></div>';}).join('');}else if(type==='like'){var d2=await api('/rest/v1/posts?select=*,author_id(nickname,level)&status=eq.published&order=like_count.desc&limit=20');rl.innerHTML=(!d2||!d2.length)?'<div class="empty">暂无</div>':d2.map(function(p,i){return'<div class="rank-item"><div class="rank-no '+(i<3?'top'+(i+1):'')+'">'+(i+1)+'</div><div style="flex:1;margin-left:6px"><div style="font-size:13px">'+esc(p.title)+'</div><div style="font-size:11px;color:#999">👤'+esc(p.author_id?p.author_id.nickname||'':'')+'</div></div><div style="font-size:13px;color:#7B68EE;font-weight:600">👍'+p.like_count+'</div></div>';}).join('');}else{var d3=await api('/rest/v1/profiles?select=*&order=exp.desc&limit=20');rl.innerHTML=(!d3||!d3.length)?'<div class="empty">暂无</div>':d3.map(function(u,i){return'<div class="rank-item"><div class="rank-no '+(i<3?'top'+(i+1):'')+'">'+(i+1)+'</div><div style="flex:1;margin-left:6px;font-size:13px">'+esc(u.nickname)+(u.role==='admin'?'<span class="lv" style="background:#e5484d">管理</span>':'')+'</div><div style="font-size:12px;color:#7B68EE;font-weight:600"><span class="lv" style="background:#7B68EE">Lv'+u.level+'</span>⚡'+u.exp+'</div></div>';}).join('');}}catch(e){rl.innerHTML='<div class="empty">加载失败</div>';}}

function pomoStart(){var b=$('pomoBtn');if(!b)return;if(pomoT){clearInterval(pomoT);pomoT=null;b.textContent='继续';var ps=$('pomoState');if(ps)ps.textContent='已暂停';return;}var h=parseInt(($('pomoH')||{}).value)||0,m=parseInt(($('pomoM')||{}).value)||0,s=parseInt(($('pomoS')||{}).value)||0;pomoL=h*3600+m*60+s;if(pomoL<=0){toast('请设置时间');return;}b.textContent='暂停';var ps2=$('pomoState');if(ps2)ps2.textContent='专注中…';pomoT=setInterval(function(){pomoL--;if(pomoL<=0){clearInterval(pomoT);pomoT=null;b.textContent='开始';var ps3=$('pomoState');if(ps3)ps3.textContent='🍅完成！';toast('🍅番茄完成！');return;}pomoRender();},1000);}
function pomoReset(){if(pomoT){clearInterval(pomoT);pomoT=null;}var b=$('pomoBtn');if(b)b.textContent='开始';var ps=$('pomoState');if(ps)ps.textContent='自定义时/分/秒';pomoL=1500;try{pomoRender();}catch(e){}}
function pomoRender(){var pt=$('pomoTime');if(!pt)return;var h=String(Math.floor(pomoL/3600)).padStart(2,'0'),m=String(Math.floor(pomoL%3600/60)).padStart(2,'0'),s=String(pomoL%60).padStart(2,'0');pt.textContent=(h>0?h+':':'')+m+':'+s;}
function renderCourses(){var cl=$('courseList');if(!cl)return;cl.innerHTML=COURSES.map(function(c,i){return'<div class="his-card" onclick="location.href=\''+c.u+'\'"><span style="flex:1;font-size:13px">'+(c.p==='bili'?'🔵':'🔴')+c.t+'</span><span style="font-size:11px;color:'+(c.p==='bili'?'#fb7299':'#161823')+'">'+(c.p==='bili'?'B站':'抖音')+'</span><span style="color:#6A5ACD;font-size:12px;cursor:pointer;margin-left:6px" onclick="event.stopPropagation();favCourse('+i+')">⭐</span></div>';}).join('');}
async function favCourse(idx){if(!me){toast('请先登录');needLogin();return;}try{var r=await api('/rest/v1/favorites?user_id=eq.'+me.id+'&target_type=eq.course&target_id=eq.'+idx+'&limit=1');if(r&&r.length){await dbD('favorites','user_id=eq.'+me.id+'&target_type=eq.course&target_id=eq.'+idx);toast('已取消');}else{await dbI('favorites',{user_id:me.id,target_type:'course',target_id:idx});toast('⭐已收藏');}}catch(e){toast('失败');}}

function showAt(){var sel=$('atSel');if(!sel)return;if(!me){sel.style.display='none';return;}try{api('/rest/v1/profiles?select=nickname,id&role=eq.admin&limit=50').then(function(admins){api('/rest/v1/followers?select=following_id&follower_id=eq.'+me.id+'&limit=200').then(function(follows){var list=[];if(admins)list=list.concat(admins.filter(function(a){return a.id!==me.id;}));if(follows&&follows.length){var ids=follows.map(function(f){return f.following_id;});api('/rest/v1/profiles?select=nickname,id&id=in.('+ids.join(',')+')').then(function(fs){if(fs)list=list.concat(fs.filter(function(f){return f.id!==me.id;}));list=list.filter(function(v,i,a){return a.findIndex(function(x){return x.id===v.id;})===i;});sel.innerHTML=list.length?list.map(function(u){return'<div class="at-i" onclick="insertAt(\''+esc(u.nickname)+'\')">@'+esc(u.nickname)+'</div>';}).join(''):'<div class="at-i">可@管理员及关注的人</div>';sel.style.display='block';});}else{sel.innerHTML='<div class="at-i">可@管理员及关注的人</div>';sel.style.display='block';}}).catch(function(){sel.innerHTML='<div class="at-i">可@管理员及关注的人</div>';sel.style.display='block';});}).catch(function(){sel.style.display='none';});}catch(e){sel.style.display='none';}}
function insertAt(name){var inp=$('pContent')||$('cmInput');if(inp)inp.value+='@'+name+' ';var as=$('atSel');if(as)as.style.display='none';if(inp&&inp.id==='cmInput')inp.focus();}

async function loadRes(type){resType=type;try{var rt1=$('resTab1'),rt2=$('resTab2');if(rt1)rt1.classList.toggle('on',type==='video');if(rt2)rt2.classList.toggle('on',type==='app');}catch(e){}var rl=$('resList');if(!rl)return;rl.innerHTML='<div class="empty">加载中...</div>';try{var d=await api('/rest/v1/resources?select=*&type=eq.'+type+'&order=created_at.desc');if(!d||!d.length){rl.innerHTML='<div class="empty">暂无内容</div>';return;}var isAdmin=me&&me.role==='admin';if(type==='video'){rl.innerHTML=d.map(function(r){return'<div class="video-card"><div class="video-cover" onclick="location.href=\''+esc(r.link)+'\'">▶️</div><div class="video-info"><div class="vt">'+esc(r.title)+'<span class="lv" style="margin-left:4px;background:#7B68EE">'+(r.pan_type||'外站')+'</span></div><div class="vs">'+esc(r.description||'')+'·点击观看</div>'+(isAdmin?'<div style="margin-top:4px"><span style="color:#e5484d;font-size:11px;cursor:pointer" onclick="delRes('+r.id+')">🗑删除</span></div>':'')+'</div></div>';}).join('');}else{rl.innerHTML=d.map(function(r){return'<div class="app-card" onclick="openAppDetail('+r.id+')"><div class="ac-top"><div class="ac-icon" style="background:#eee;text-align:center;line-height:48px;font-size:22px">'+(r.icon?'<img src="'+esc(r.icon)+'" class="ac-icon">':'📱')+'</div><div><div class="ac-title">'+esc(r.title)+'<span class="lv" style="margin-left:4px;background:#ff9500">'+(r.size_mb||'')+'</span></div><div class="ac-sub">'+esc(r.description||'')+'·📥'+(r.downloads||0)+'次</div>'+(isAdmin?'<div style="margin-top:4px"><span style="color:#e5484d;font-size:11px;cursor:pointer" onclick="event.stopPropagation();delRes('+r.id+')">🗑删除</span></div>':'')+'</div></div></div>';}).join('');}}catch(e){rl.innerHTML='<div class="empty">加载失败</div>';}}
async function delRes(rid){if(!confirm('确定删除？'))return;try{await dbD('resources','id=eq.'+rid);toast('已删除');loadRes(resType);}catch(e){toast('失败');}}
function initResPost(){var rc=$('resTypeChips');if(!rc)return;rc.innerHTML=[['video','🎬视频'],['app','📱应用']].map(function(x){return'<div class="chip '+(x[0]===resType?'on':'')+'" onclick="pickResType(this,\''+x[0]+'\')">'+x[1]+'</div>';}).join('');var re=$('resErr');if(re)re.textContent='';}
function pickResType(el,k){resType=k;document.querySelectorAll('#resTypeChips .chip').forEach(function(x){x.classList.remove('on');});el.classList.add('on');}
async function submitRes(){if(!me||me.role!=='admin'){toast('仅管理员');return;}var rt=$('resTitle'),rd=$('resDesc'),rl=$('resLink'),rs=$('resSize');if(!rt||!rd||!rl)return;var title=rt.value.trim(),desc=rd.value.trim(),link=rl.value.trim(),size=rs?rs.value.trim():'';if(!title||!link){var re=$('resErr');if(re)re.textContent='请填标题和链接';return;}var icon='';var ri=$('resImg');var f=ri?ri._selected:null;try{if(f)icon=await uploadImg(f);await dbI('resources',{title:title,description:desc,type:resType,link:link,icon:icon,size_mb:size||null,created_by:me.id});toast('✅已发布');rt.value='';rd.value='';rl.value='';if(rs)rs.value='';if(ri){ri.value='';ri._selected=null;}var rp=$('resImgPreview');if(rp)rp.innerHTML='';goPage('resourcePage');}catch(e){var re2=$('resErr');if(re2)re2.textContent='失败：'+e.message;}}
async function openAppDetail(id){try{var r=await api('/rest/v1/resources?id=eq.'+id);var d=r&&r[0];if(!d)return;var fav=me?await isFav('app',d.id):false;var ab=$('appDetailBox');if(!ab)return;ab.innerHTML='<div style="background:#fff;border-radius:12px;padding:16px;text-align:center;margin-bottom:10px">'+(d.icon?'<img src="'+esc(d.icon)+'" style="width:72px;height:72px;border-radius:14px;object-fit:cover;margin-bottom:8px">':'<div style="width:72px;height:72px;border-radius:14px;background:#eee;line-height:72px;margin:0 auto 8px;font-size:28px">📱</div>')+'<div style="font-size:17px;font-weight:700">'+esc(d.title)+'</div></div><div style="background:#fff;border-radius:12px;padding:14px;font-size:13px;line-height:1.7;color:#444;margin-bottom:10px">'+esc(d.description||'暂无介绍')+'</div><div class="stat-card"><div><div class="stat-num">'+(d.downloads||0)+'</div><div class="stat-label">下载</div></div><div><div class="stat-num">'+(d.size_mb||'--')+'</div><div class="stat-label">大小</div></div></div><div class="detail-actions"><button class="action-btn '+(fav?'on':'')+'" style="border-color:#7B68EE;color:#7B68EE" onclick="favRes(\'app\','+d.id+')">⭐'+(fav?'已收藏':'收藏')+'</button><button class="action-btn" style="border-color:#ff9500;color:#ff9500" onclick="location.href=\''+esc(d.link)+'\'">🔗下载</button>'+(me&&me.role==='admin'?'<button class="action-btn" style="color:#e5484d" onclick="delRes('+d.id+')">🗑删除</button>':'')+'</div>';goPage('appDetailPage');}catch(e){toast('加载失败');}}
async function favRes(type,rid){if(!me){toast('请先登录');needLogin();return;}try{var r=await api('/rest/v1/favorites?user_id=eq.'+me.id+'&target_type=eq.'+type+'&target_id=eq.'+rid+'&limit=1');if(r&&r.length){await dbD('favorites','user_id=eq.'+me.id+'&target_type=eq.'+type+'&target_id=eq.'+rid);toast('已取消');}else{await dbI('favorites',{user_id:me.id,target_type:type,target_id:rid});toast('⭐已收藏');}loadRes(resType);}catch(e){toast('失败');}}

async function loadAdmin(tab){try{var a1=$('aTab1'),a2=$('aTab2'),a3=$('aTab3');if(a1)a1.classList.toggle('on',tab==='reports');if(a2)a2.classList.toggle('on',tab==='punish');if(a3)a3.classList.toggle('on',tab==='posts');}catch(e){}var ab=$('adminBox');if(!ab)return;if(tab==='posts'){try{var d=await api('/rest/v1/posts?select=*,author_id(nickname,level)&status=eq.published&order=created_at.desc&limit=100');ab.innerHTML='<div class="tip" style="margin-bottom:8px">共'+d.length+'个帖子 · 勾选后批量删除</div><div style="display:flex;gap:8px;margin-bottom:8px"><button class="btn" onclick="document.querySelectorAll(\'.ap\').forEach(function(x){x.checked=true;})">全选</button><button class="btn" style="background:#e5484d" onclick="delSelPosts()">删除选中</button></div>'+d.map(function(p){return'<label style="display:flex;align-items:center;padding:8px 0;border-bottom:1px solid #f4f4f4;font-size:13px"><input type="checkbox" class="ap" value="'+p.id+'" style="margin-right:8px">'+esc(p.title)+'<span style="margin-left:auto;color:#999;font-size:11px">👤'+esc(p.author_id?p.author_id.nickname||'':'')+'</span></label>';}).join('');}catch(e){ab.innerHTML='<div class="empty">加载失败</div>';}}else if(tab==='reports'){try{var d2=await api('/rest/v1/reports?status=eq.pending&order=created_at.desc');if(!d2||!d2.length){ab.innerHTML='<div class="empty">没有待处理举报🎉</div>';return;}var h='<div class="tip" style="margin-bottom:8px">共'+d2.length+'条</div>';for(var i=0;i<d2.length;i++){var r=d2[i],target='',content='';try{if(r.target_type==='post'){var p=await api('/rest/v1/posts?id=eq.'+r.target_id);if(p&&p[0]){target='帖子：'+p[0].title;content=p[0].content;}}else{var c=await api('/rest/v1/comments?id=eq.'+r.target_id);if(c&&c[0]){target='评论#'+r.target_id;content=c[0].content;}}}catch(e){}h+='<div class="comment-box"><div style="font-size:13px;font-weight:600">🚩'+esc(r.reason)+'</div><div style="font-size:11px;color:#999;margin:4px 0">'+esc(target)+'</div><div style="font-size:12px;color:#555;background:#f7f8fa;border-radius:8px;padding:8px;margin:8px 0">'+esc(content)+'</div><div style="display:flex;gap:8px"><button class="btn" style="background:#999;flex:1" onclick="handleReport('+r.id+',\'ignore\')">忽略</button><button class="btn" style="flex:1" onclick="handleReport('+r.id+',\'delete\')">删内容</button><button class="btn" style="background:#e5484d;flex:1" onclick="handleReport('+r.id+',\'punish\')">删+扣分</button></div></div>';}ab.innerHTML=h;}catch(e){ab.innerHTML='<div class="empty">加载失败</div>';}}else{ab.innerHTML='<div class="tip" style="margin-bottom:8px">按QQ号查找用户</div><input id="punishQQ" class="inp" placeholder="输入QQ号"><button class="btn" onclick="findUser()">查找</button><div id="userInfo" style="margin-top:10px"></div>';}}
async function delSelPosts(){var sel=[].slice.call(document.querySelectorAll('.ap:checked')).map(function(x){return x.value;});if(!sel.length){toast('请先选择');return;}if(!confirm('确定删除'+sel.length+'个帖子？'))return;for(var i=0;i<sel.length;i++){try{await dbR('delete_post',{pid:sel[i]});}catch(e){}}toast('✅已删除');loadAdmin('posts');}
async function findUser(){var pq=$('punishQQ');if(!pq)return;var kw=pq.value.trim();try{var d=await api('/rest/v1/profiles?select=*&qq=eq.'+kw+'&limit=1');var ui=$('userInfo');if(!ui)return;if(!d||!d.length){ui.innerHTML='<div class="empty">没找到</div>';return;}var u=d[0];ui.innerHTML='<div class="comment-box"><div style="font-weight:600">👤'+esc(u.nickname)+'(QQ:'+esc(u.qq||'-')+')</div><div style="font-size:12px;color:#555;background:#f7f8fa;border-radius:8px;padding:8px;margin:6px 0">Lv'+u.level+'·🪙'+u.coins+'·💯'+u.credit+(u.is_banned?'·⛔已封号':'')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'credit\',10)">扣10分</button><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'credit\',50)">扣50分</button><button class="btn" onclick="punish(\''+u.id+'\',\'mute\',1)">禁1天</button><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'ban\',0)">封号</button><button class="btn" style="background:#e5484d" onclick="punish(\''+u.id+'\',\'device_ban\',0)">封设备</button><button class="btn" style="background:#999" onclick="punish(\''+u.id+'\',\'unban\',0)">解封</button></div></div>';}catch(e){var ui2=$('userInfo');if(ui2)ui2.innerHTML='<div class="empty">查询失败</div>';}}
async function punish(uid,action,amount){try{var r=await dbR('admin_punish',{p_user_id:uid,p_action:action,p_amount:amount,p_detail:action==='mute'?'禁言':(action==='ban'?'封号':(action==='device_ban'?'封设备':'扣分'))});toast(r==='OK'?'✅已执行':('⚠️'+r));setTimeout(function(){findUser();},600);}catch(e){toast('失败');}}
async function handleReport(rid,act){try{if(act==='ignore'){await dbU('reports','id=eq.'+rid,{status:'ignored'});toast('已忽略');}else{var r=await api('/rest/v1/reports?id=eq.'+rid);var rep=r&&r[0];if(rep){if(rep.target_type==='post'){var p=await api('/rest/v1/posts?id=eq.'+rep.target_id);if(p&&p[0]){if(act==='punish')await dbR('admin_punish',{p_user_id:p[0].author_id,p_action:'credit',p_amount:10,p_detail:'举报成立'});await dbR('delete_post',{pid:rep.target_id});}}else{await dbR('delete_comment',{cid:rep.target_id});}await dbU('reports','id=eq.'+rid,{status:'handled'});if(rep.reporter_id)dbR('reward_report',{p_reporter_id:rep.reporter_id}).catch(function(){});toast('✅已处理');}}loadAdmin('reports');}catch(e){toast('处理失败');}}

try{drawCaptcha();}catch(e){}
try{if(curUser2())showMain();else goPage('loginPage');}catch(e){goPage('loginPage');}